"""Apresenta vínculo criptográfico, vigência e confiança sem fundir conclusões."""
import html
from reportlab.platypus import PageBreak
from .pdf_layout import AnalysisPDF,pdf_styles,p,heading,table,WIDTH

LIMIT='Nenhum caminho até âncora oficial foi validado e nenhuma LCR foi obtida nesta consulta. Isso deixa confiança e revogação indeterminadas; não demonstra revogação nem ausência dela. A verificação de um vínculo com um intermediário candidato não equivale à validação integral de uma cadeia RFC 5280.'
TIME='O certificado disponível da AC URNA tem término de validade em 18/07/2026. Ele é o candidato cujo nome, identificadores e chave conferem para 14 unidades seção/turno da amostra; as datas declaradas nesses VSC são posteriores ao término. Esse é um apontamento sobre o certificado intermediário disponível. Não foi obtido documento que explique a situação, nem se pressupõe renovação com a mesma chave. O certificado de ponta permanece com sua própria validade, verificada separadamente.'
SOURCE='Os três candidatos foram extraídos como dados do pacote técnico já preservado, obtido de espelho de terceiros e fixado por SHA256. Não são promovidos automaticamente a âncoras. O acesso direto aos endereços candidatos e às LCR resultou em HTTP 403 ou erro TLS. Nenhuma verificação TLS foi desativada. Uma falha de acesso deste ambiente não demonstra que o documento inexiste ou seja inacessível por todos os meios.'
METHOD='A conferência verifica nome do emissor, AKI/SKI, indicação de CA, permissão keyCertSign e a assinatura do certificado de ponta com a chave do candidato. Certificados e LCR assinam seus bytes TBS diretamente; não usam o wrapper SHA512(hash) dos arquivos VSC. ECDSA P-521 e Ed521 são suportados. Vigência, assinatura matemática, caminho até âncora e revogação são campos separados. Políticas, nomes, todas as extensões e o caminho completo não são validados por esta rotina de um vínculo.'
CRL='O avaliador implementado aceita somente uma LCR completa e direta, com assinatura verificável e intervalo que cubra o instante avaliado. Rejeita resultados conclusivos para LCR ausente, fora do período, delta/escopo não suportado, chave ou emissor incompatível. Não infere status histórico a partir de uma LCR posterior. Nenhuma LCR real pôde ser lida nesta rodada; os caminhos de verificação foram testados apenas com dados sintéticos controlados.'


def render(destination,summary,links,cas,attempts,pending):
    esc=lambda v:html.escape(str(v))
    lead=f"Foram conferidas {summary['section_turns']} ocorrências de certificados, correspondentes a {summary['unique_leaf_certificates']} certificados de ponta distintos, na mesma amostra de {summary['sections']} seções nos dois turnos."
    outcome=f"As {summary['certificate_signatures_match']} assinaturas dos certificados de ponta conferem com as chaves de três intermediários candidatos. Em {summary['issuer_period_compatible']} unidades, o período do candidato é compatível com a data declarada; em {summary['issuer_period_outside']}, o candidato disponível já estava fora do intervalo de validade."
    headers=['Procedimento','Quantidade','Conclusão permitida']
    rows=[['Assinatura da ponta com candidato',summary['certificate_signatures_match'],'Confere com a chave candidata; não é confiança completa'],['Vigência do intermediário compatível',summary['issuer_period_compatible'],'Compatibilidade com a data declarada, não carimbo de tempo'],['Vigência do intermediário incompatível',summary['issuer_period_outside'],'Pendência documental na amostra'],['Caminhos completos verificados',0,'Não concluídos; falta âncora e caminho verificados'],['Revogação conclusiva',0,'LCR não obtida; status indeterminado nas 48 unidades']]
    ca_rows=[[r['name'],r['issuer_cn'],r['not_after'][:10],r['der_sha256']] for r in cas.to_dict('records')]
    pending_rows=[[r['uf'],r['municipality'],f'{r["zone"]}/{r["section"]}',r['turn'],r['signed_at'][:8],r['issuer_candidate']] for r in pending.to_dict('records')]
    unit_rows=[[r['uf'],r['municipality'],f'{r["zone"]}/{r["section"]}',r['turn'],r.get('issuer_candidate'),('Compatível' if r.get('issuer_time_status')=='compativel_em_todos_os_fusos_considerados' else 'Fora do intervalo'),'Confere' if r['signature_status']=='confere_com_candidato' else r['signature_status']] for r in links.to_dict('records')]
    def tbl(head,data):return '<table><thead><tr>'+''.join('<th>'+esc(v)+'</th>' for v in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+esc(v)+'</td>' for v in row)+'</tr>' for row in data)+'</tbody></table>'
    resources=[('vinculos.csv','48 vínculos e campos separados'),('intermediarios.csv','Candidatos e proveniência'),('tentativas.csv','Tentativas de obtenção, HTTP/TLS e datas'),('pendencias_vigencia.csv','14 ocorrências com vigência incompatível'),('fontes_resumo.json','Fontes e política de confiança'),('resumo.json','Síntese desta execução'),('relatorio.pdf','PDF'),('../ed521/relatorio.html','Verificações de hardware anteriores'),('../../../../docs/CADEIA_CERTIFICADOS.md','Método, reprodução e pendências')]
    page=f'''<!doctype html><html lang="pt-BR"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Cadeia de certificados da amostra — 2026</title><style>body{{font:17px/1.65 system-ui;color:#183447;background:#f1f5f7;margin:0}}main{{max-width:1100px;margin:auto;background:white;padding:2rem}}h1{{line-height:1.2}}h2{{color:#12677a;margin-top:2rem}}.finding,.limit{{padding:1rem;background:#edf4f7;border-left:5px solid #12677a}}.limit{{background:#fff8e9;border-color:#bd7427}}table{{border-collapse:collapse;width:100%;font-size:.85rem}}td,th{{padding:.5rem;text-align:left;border-bottom:1px solid #ccd9df;overflow-wrap:anywhere}}th{{background:#edf4f7}}.scroll{{overflow:auto}}a{{color:#075f8a}}</style><main>
<p>Etapa 5 · vínculo com intermediários, vigência e revogação</p><h1>Vínculos criptográficos conferem; cadeia completa e revogação continuam indeterminadas</h1><p>{esc(lead)}</p><p class="finding">{esc(outcome)}</p><p class="limit">{esc(LIMIT)}</p><div class="scroll">{tbl(headers,rows)}</div>
<h2>O que falta entre a ponta e a confiança</h2><p>Certificado da urna → assinatura confere com candidato intermediário → emissor desse candidato não obtido/verificado → caminho até âncora não concluído. Uma raiz citada pelo nome, um certificado autoassinado ou um hash publicado numa cópia não são promovidos a confiança automaticamente.</p><p>{esc(METHOD)}</p><p>{esc(SOURCE)}</p><p>Foram registradas {summary['access_attempts']} tentativas: {summary['tls_errors']} erros TLS e nenhuma resposta HTTP 200. As tentativas de LCR correspondem aos pontos de distribuição presentes nos certificados. Os endereços de certificados raiz são candidatos citados em referência de terceiros, sem obtenção direta confirmada.</p>
<h2>Intermediários candidatos e período de validade</h2><div class="scroll">{tbl(['Candidato','Emissor indicado','Validade até (UTC)','SHA256 DER'],ca_rows)}</div><p>{esc(TIME)}</p><p>Não há conclusão sobre a causa da incompatibilidade temporal. A concordância da assinatura não altera as datas do certificado disponível e não explica escolhas dos eleitores. Os nomes dos emissores não substituem os certificados ainda faltantes.</p>
<h2>As 14 ocorrências que exigem esclarecimento</h2><div class="scroll">{tbl(['UF','Município TSE','Zona/seção','Turno','Data declarada AAAAMMDD','Candidato'],pending_rows)}</div>
<h2>Revogação: implementado versus obtido</h2><p>{esc(CRL)}</p><p>Dados sintéticos de LCR válidas, com serial presente, ausente, assinatura errada, período vencido e delta/escopo não suportado foram usados para testar a classificação. Esses testes não são evidência de status de revogação dos certificados reais.</p>
<h2>Inventário completo da amostra</h2><div class="scroll">{tbl(['UF','Município TSE','Zona/seção','Turno','Candidato','Vigência do candidato','Assinatura da ponta'],unit_rows)}</div>
<h2>Fontes, tabelas e reprodução</h2><ul>{''.join('<li><a href="'+url+'">'+esc(label)+'</a></li>' for url,label in resources)}</ul><p>Referências: <a href="https://www.rfc-editor.org/rfc/rfc5280.html">RFC 5280</a> e <a href="https://www.tse.jus.br/eleicoes/urna-eletronica/seguranca-da-urna/hash/resumos-digitais-hashes-das-eleicoes-2026-1o-e-2o-turnos">página de hashes do TSE</a>. A execução não implementa todo o algoritmo da RFC. A fonte dos candidatos, a limitação do espelho e as tentativas são preservadas.</p>
<h2>Próximo passo documental</h2><p>Obter os certificados emissores e a âncora com proveniência oficial, esclarecer qual certificado de AC URNA era aplicável às datas de 2026 e obter evidência de revogação histórica compatível. Nenhum contato externo foi enviado. CEPESC, confirmação oficial do layout, eventos dos logs, BU independente e ato de nulos técnicos continuam frentes distintas.</p></main></html>'''
    (destination/'relatorio.html').write_text(page,encoding='utf8')
    styles=pdf_styles();story=[heading('Cadeia de certificados — 2026','inicio',styles),p(lead,styles,'Deck'),p(outcome,styles),p(LIMIT,styles),table(['Procedimento','Qtd.','Conclusão permitida'],rows,[WIDTH*.36,WIDTH*.13,WIDTH*.51],styles,small=True),p('Zero caminhos completos ou revogações conclusivas significa procedimento não concluído com a evidência disponível. Não é demonstração de ausência de irregularidades. As contagens são por seção/turno; o mesmo certificado pode aparecer nos dois turnos.',styles,'Small'),PageBreak(),heading('Método, fontes e alcance','metodo',styles),p(METHOD,styles),p(SOURCE,styles),p(CRL,styles),p('A verificação de um vínculo não valida integralmente políticas, nomes, extensões ou todo o caminho da RFC 5280. Nenhum intermediário do espelho foi promovido a âncora. O certificado de ponta, a vigência da CA e a evidência de revogação permanecem separados nas tabelas.',styles),p('Próximo passo: certificados e âncora com proveniência oficial, certificado de AC URNA aplicável às datas e evidência histórica de revogação. Nenhum contato externo foi enviado. Fontes, hashes e tentativas estão no HTML e em docs/CADEIA_CERTIFICADOS.md.',styles),PageBreak(),heading('Pendência de vigência da AC URNA','vigencia',styles),p(TIME,styles),p('As ocorrências abaixo são um apontamento sobre o candidato disponível, sem classificação automática de causa, fraude ou invalidação dos votos. Data declarada no VSC: AAAAMMDD; Z/S = zona/seção; Tº = turno.',styles),table(['UF','Município TSE','Z/S','Tº','Data VSC','Candidato'],pending_rows,[WIDTH*x for x in (.07,.18,.16,.08,.23,.28)],styles,small=True)]
    for offset in range(0,len(unit_rows),16):
        story.extend([PageBreak(),heading(f'Vínculos {offset+1}–{min(offset+16,len(unit_rows))}','vinculos-'+str(offset),styles),p('Confere = assinatura da ponta com a chave candidata. Vigência refere-se ao intermediário. Todos os caminhos permanecem incompletos e a revogação indeterminada. Z/S = zona/seção; Tº = turno.',styles,'Small'),table(['UF','Mun. TSE','Z/S','Tº','Candidato','Vigência CA','Assinatura'],unit_rows[offset:offset+16],[WIDTH*x for x in (.06,.13,.12,.07,.19,.25,.18)],styles,small=True)])
    AnalysisPDF(destination/'relatorio.pdf',title='Cadeia de certificados da amostra — 2026',styles=styles).build(story)
